<style>
    .lf-dashboard{--lf-blue:#1769aa;--lf-deep:#123b67;--lf-ink:#172b4d;--lf-muted:#65758b;--lf-line:#e4ebf3;--lf-bg:#f5f8fc;--lf-green:#159570;--lf-amber:#d99516;--lf-red:#d9534f;background:var(--lf-bg);margin:-8px -8px 22px;padding:0 0 28px;min-height:calc(100vh - 70px);color:var(--lf-ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.lf-dashboard *{box-sizing:border-box}.lf-shell{max-width:1500px;margin:auto;padding:0 10px}.lf-hero{position:relative;overflow:hidden;border-radius:20px;background:linear-gradient(135deg,var(--lf-deep),var(--lf-blue) 58%,#25a4c8);padding:27px 30px;color:#fff;box-shadow:0 16px 38px rgba(20,66,108,.2)}.lf-hero:after{content:"";position:absolute;right:-80px;top:-150px;width:320px;height:320px;border-radius:50%;background:rgba(255,255,255,.11)}.lf-hero-main{position:relative;z-index:1;display:flex;align-items:flex-start;justify-content:space-between;gap:22px}.lf-eyebrow{font-size:.7rem;letter-spacing:.16em;text-transform:uppercase;font-weight:800;color:rgba(255,255,255,.72)}.lf-title{font-size:clamp(1.55rem,3vw,2.4rem);line-height:1.08;font-weight:850;letter-spacing:-.04em;margin:8px 0}.lf-subtitle{font-size:.88rem;line-height:1.55;color:rgba(255,255,255,.82);max-width:690px;margin:0}.lf-hero-meta{text-align:right;min-width:190px}.lf-live{display:inline-flex;align-items:center;gap:8px;border-radius:999px;padding:8px 12px;background:rgba(255,255,255,.16);font-size:.74rem;font-weight:800;white-space:nowrap}.lf-live i{width:8px;height:8px;border-radius:50%;background:#86f4d1;box-shadow:0 0 0 5px rgba(134,244,209,.14);animation:lfPulse 1.8s infinite}.lf-updated{font-size:.7rem;color:rgba(255,255,255,.7);margin-top:9px}.lf-period{display:inline-flex;gap:7px;align-items:center;margin-top:18px;padding:7px 12px;border-radius:999px;background:rgba(255,255,255,.14);font-size:.74rem;position:relative;z-index:1}.lf-alert{display:none;margin:14px 0 0;padding:10px 13px;border:1px solid #f3ddb0;border-radius:10px;background:#fff8e9;color:#a16b12;font-size:.75rem;align-items:center;gap:8px}.lf-alert.show{display:flex}.lf-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-top:16px}.lf-card{background:#fff;border:1px solid var(--lf-line);border-radius:15px;box-shadow:0 5px 18px rgba(24,49,80,.055)}.lf-kpi{padding:17px 18px;border-top:4px solid var(--lf-blue);min-width:0}.lf-kpi.green{border-top-color:var(--lf-green)}.lf-kpi.amber{border-top-color:var(--lf-amber)}.lf-kpi.red{border-top-color:var(--lf-red)}.lf-label{font-size:.73rem;color:var(--lf-muted);font-weight:750;text-transform:uppercase;letter-spacing:.05em}.lf-value{margin-top:8px;font-weight:850;font-size:clamp(1.15rem,2vw,1.5rem);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.lf-kpi.blue .lf-value{color:var(--lf-blue)}.lf-kpi.green .lf-value{color:var(--lf-green)}.lf-kpi.amber .lf-value{color:#b27b14}.lf-kpi.red .lf-value{color:#c34d48}.lf-note{color:#8a97a8;font-size:.72rem;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.lf-heading{display:flex;align-items:end;justify-content:space-between;gap:12px;margin:22px 0 10px}.lf-heading h3{font-size:1rem;font-weight:850;margin:0}.lf-heading small{font-size:.72rem;color:var(--lf-muted)}.lf-systems{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.lf-system{padding:16px;min-height:145px}.lf-system-head{display:flex;justify-content:space-between;align-items:center;gap:9px}.lf-system-name{font-weight:850;font-size:.9rem}.lf-status{font-size:.65rem;font-weight:800;padding:5px 8px;border-radius:999px;background:#e3f7ef;color:#147d61}.lf-status.down{background:#fff3df;color:#a56d12}.lf-system-total{font-size:1.28rem;font-weight:850;margin:17px 0 10px}.lf-system-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px}.lf-system-stats b{display:block;font-size:.78rem}.lf-system-stats small{display:block;color:var(--lf-muted);font-size:.65rem;margin-top:2px}.lf-system-foot{margin-top:12px;color:#8a97a8;font-size:.67rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.lf-grid{display:grid;grid-template-columns:1.35fr .95fr;gap:14px;margin-top:14px}.lf-panel{padding:18px;min-height:300px}.lf-panel-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:14px}.lf-panel-head h3{font-size:1rem;font-weight:850;margin:0}.lf-panel-head p{font-size:.72rem;color:var(--lf-muted);margin:3px 0 0}.lf-panel-head i{color:var(--lf-blue);font-size:1.05rem}.lf-chart{height:205px}.lf-chart svg{width:100%;height:100%;display:block}.lf-axis{display:flex;justify-content:space-between;color:#9aa7ba;font-size:.64rem;margin-top:3px}.lf-debt-total{padding:14px;border-radius:12px;background:#fff5e3;border:1px solid #f3dfba;margin-bottom:15px}.lf-debt-total span{display:block;color:#9a6b19;font-size:.7rem;font-weight:700}.lf-debt-total strong{display:block;color:#ac7410;font-size:1.45rem;margin-top:5px}.lf-row{margin:12px 0}.lf-row-head{display:flex;justify-content:space-between;gap:10px;font-size:.73rem;font-weight:750}.lf-row-head span:last-child{color:var(--lf-muted);white-space:nowrap}.lf-bar{height:7px;background:#edf1f6;border-radius:99px;overflow:hidden;margin-top:6px}.lf-bar i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#d99516,#f4c96d)}.lf-services{display:grid;gap:4px}.lf-service{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:11px 0;border-bottom:1px solid #eef2f6;font-size:.74rem}.lf-service:last-child{border-bottom:0}.lf-service-name{font-weight:750;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.lf-service-value{text-align:right;white-space:nowrap}.lf-service-value strong{display:block;font-size:.76rem}.lf-service-value small{color:var(--lf-muted);font-size:.64rem}.lf-readout{display:grid;gap:10px}.lf-signal{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px;border-radius:11px;background:#f7f9fc;font-size:.74rem}.lf-signal strong{font-size:.77rem}.lf-empty{display:grid;place-items:center;height:205px;color:var(--lf-muted);font-size:.75rem}@keyframes lfPulse{50%{opacity:.35;transform:scale(.8)}}
    @media(max-width:1050px){.lf-systems{grid-template-columns:repeat(2,1fr)}.lf-grid{grid-template-columns:1fr}}
    @media(max-width:700px){.lf-dashboard{margin:0 -2px 18px;padding-bottom:16px}.lf-shell{padding:0 2px}.lf-hero{padding:21px 18px;border-radius:15px}.lf-hero-main{display:block}.lf-title{font-size:1.45rem}.lf-subtitle{font-size:.78rem}.lf-hero-meta{text-align:left;margin-top:17px}.lf-kpis{grid-template-columns:repeat(2,1fr);gap:9px}.lf-kpi{padding:13px 12px;border-radius:12px}.lf-label{font-size:.64rem}.lf-value{font-size:1rem}.lf-note{font-size:.65rem}.lf-systems{grid-template-columns:1fr}.lf-system{border-radius:13px}.lf-panel{padding:14px;border-radius:13px}.lf-heading{align-items:flex-start;flex-direction:column;gap:3px}}
</style>
<style>
    .lf-dashboard .lf-grid{display:none}.lf-dashboard .lf-eyebrow,.lf-dashboard .lf-subtitle,.lf-dashboard .lf-period,.lf-dashboard .lf-hero-meta{display:none}.lf-dashboard .lf-hero{padding:15px 20px}.lf-dashboard .lf-hero-main{align-items:center}.lf-dashboard .lf-title{margin:0}.lf-session-bar{display:flex;align-items:end;justify-content:space-between;gap:14px;margin:12px 0 16px;padding:12px 14px;background:#fff;border:1px solid var(--lf-line);border-radius:13px;box-shadow:0 5px 18px rgba(24,49,80,.055)}.lf-session-field{display:grid;gap:5px;min-width:220px}.lf-session-field label{font-size:.68rem;font-weight:800;color:var(--lf-muted);text-transform:uppercase;letter-spacing:.05em}.lf-session-field select{height:38px;padding:0 11px;border:1px solid #d8e2ed;border-radius:9px;background:#fff;color:var(--lf-ink);font:inherit;font-size:.78rem;outline:none}.lf-session-field select:focus{border-color:var(--lf-blue);box-shadow:0 0 0 3px rgba(23,105,170,.12)}.lf-session-live{font-size:.7rem;color:var(--lf-muted);white-space:nowrap}.lf-school-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:14px}.lf-school-card{padding:17px;min-height:260px}.lf-school-total{font-size:1.12rem;font-weight:850;color:var(--lf-blue);margin:10px 0 7px}.lf-school-card .lf-panel-head{margin-bottom:7px}.lf-school-card .lf-panel-head h3{font-size:.92rem}.lf-school-card .lf-school-total:before{content:'Paid base amount';display:block;font-size:.64rem;font-weight:700;color:var(--lf-muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:2px}.lf-school-card .lf-service{padding:9px 0}.lf-school-card .lf-empty{height:150px}@media(max-width:1050px){.lf-school-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.lf-dashboard .lf-hero{padding:13px 15px}.lf-session-bar{display:block;margin-top:10px}.lf-session-field{min-width:0}.lf-session-live{display:block;margin-top:8px}.lf-school-grid{grid-template-columns:1fr}.lf-school-card{border-radius:13px}}
</style>

