                    <option value="all" {{ strtolower((string) ($selectedFinanceSession ?? 'all')) === 'all' ? 'selected' : '' }}>All sessions</option>
                    @foreach(($financeSessions ?? []) as $financeSession)
                        <option value="{{ $financeSession->title }}" {{ (string) ($selectedFinanceSession ?? '') === (string) $financeSession->title ? 'selected' : '' }}>{{ $financeSession->title }}{{ (string) ($financeSession->status ?? '') === '1' ? ' — current' : '' }}</option>
