            <section class="lf-card lf-panel"><div class="lf-panel-head"><div><h3>UG debt by level</h3><p>Current school-fee session</p></div><i class="fas fa-layer-group"></i></div><div class="lf-debt-total"><span>Total outstanding</span><strong id="debtPanelTotal">₦0.00</strong></div><div id="financeDebtLevels"></div></section>
