</div>

<script>
(function(){
    const root=document.getElementById('financeLive');if(!root)return;const endpoint=root.dataset.endpoint,initial=@json($payload??[]),sessionSelect=document.getElementById('financeSession');let inFlight=false;
    const financeFetch=window.fetch.bind(window);window.fetch=function(url,options){if(String(url)===endpoint){const financeUrl=new URL(url,window.location.origin);financeUrl.searchParams.set('session',sessionSelect?.value||'all');url=financeUrl.toString()}return financeFetch(url,options)};
    const money=new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',minimumFractionDigits:2});const fmt=v=>money.format(Number(v||0));const count=v=>new Intl.NumberFormat('en-NG').format(Number(v||0));const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const time=v=>{if(!v)return '—';const d=new Date(v);return isNaN(d)?'—':d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})};const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};
    function drawSystems(rows){const host=document.getElementById('financeSystems');host.innerHTML=(rows||[]).map(s=>{const sync=s.status==='syncing',down=s.status!=='ok'&&!sync;return `<article class="lf-card lf-system"><div class="lf-system-head"><div class="lf-system-name">${esc(s.label)}</div><span class="lf-status ${down?'down':''}">${sync?'Syncing…':down?'Unavailable':'Connected'}</span></div><div class="lf-system-total">${fmt(s.paid_amount||0)}</div><div class="lf-system-stats"><div><b>${count(s.paid_count)}</b><small>Successful</small></div><div><b>${count(s.count)}</b><small>Records</small></div></div><div class="lf-system-foot">${down?esc(s.error||'Source did not respond'):sync?'Waiting for first sync…':'Base amount only · latest '+time(s.last_payment_at)}</div></article>`}).join('');const online=(rows||[]).filter(s=>s.status==='ok').length;set('financeCoverage',online+'/'+(rows||[]).length+' schools connected')}
    function drawDebt(rows,total){const host=document.getElementById('financeDebtLevels');set('debtPanelTotal',fmt(total));if(!rows||!rows.length){host.innerHTML='<div class="lf-empty">No active UG debt found</div>';return}const max=Math.max(...rows.map(x=>Number(x.outstanding_amount||0)),1);host.innerHTML=rows.slice(0,10).map(r=>`<div class="lf-row"><div class="lf-row-head"><span>${esc(r.level||'Not set')} level</span><span>${fmt(r.outstanding_amount)} · ${count(r.students)} students</span></div><div class="lf-bar"><i style="width:${Math.max(2,Math.min(100,Number(r.outstanding_amount||0)/max*100))}%"></i></div></div>`).join('')}
    function drawServices(rows){const host=document.getElementById('financeServices');if(!rows||!rows.length){host.innerHTML='<div class="lf-empty">No successful payments recorded today</div>';return}host.innerHTML=rows.slice(0,8).map(r=>`<div class="lf-service"><div class="lf-service-name">${esc(r.label||'Payment')}</div><div class="lf-service-value"><strong>${fmt(r.gross_amount)}</strong><small>${count(r.invoice_count||r.payment_count)} records</small></div></div>`).join('')}
    function drawSchoolServices(rows){const host=document.getElementById('financeSchoolServices');host.innerHTML=(rows||[]).map(s=>{const services=s.services||[];return `<article class="lf-card lf-school-card"><div class="lf-panel-head"><div><h3>${esc(s.label)}</h3><p>Paid payments by description</p></div><i class="fas fa-building-columns"></i></div><div class="lf-school-total">${fmt(s.paid_amount||0)}</div>${services.length?`<div class="lf-services">${services.map(r=>`<div class="lf-service"><div class="lf-service-name">${esc(r.label||'Payment')}</div><div class="lf-service-value"><strong>${fmt(r.gross_amount)}</strong><small>${count(r.invoice_count)} records</small></div></div>`).join('')}</div>`:'<div class="lf-empty">No successful payment recorded today</div>'}</article>`}).join('')}
    function drawTrend(rows){const host=document.getElementById('financeTrend');if(!rows||!rows.length){host.innerHTML='<div class="lf-empty">No successful activity recorded today</div>';return}const points=rows.slice(-24),max=Math.max(...points.map(x=>Number(x.gross_amount||0)),1),w=760,h=195,p=12,coords=points.map((x,i)=>[p+i*(w-p*2)/Math.max(points.length-1,1),h-p-Number(x.gross_amount||0)/max*(h-p*2)]),line=coords.map((q,i)=>(i?'L':'M')+q[0].toFixed(1)+' '+q[1].toFixed(1)).join(' '),area=line+' L '+coords[coords.length-1][0]+' '+(h-p)+' L '+coords[0][0]+' '+(h-p)+' Z';host.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-label="Hourly successful collection chart"><defs><linearGradient id="lfGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#1769aa" stop-opacity=".3"/><stop offset="1" stop-color="#1769aa" stop-opacity="0"/></linearGradient></defs><path d="${area}" fill="url(#lfGradient)"/><path d="${line}" fill="none" stroke="#1769aa" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${coords.map(q=>`<circle cx="${q[0]}" cy="${q[1]}" r="3.5" fill="#fff" stroke="#1769aa" stroke-width="2"/>`).join('')}</svg>`}
    function drawReadout(data){const t=data.totals||{},d=data.debt||{},online=(data.systems||[]).filter(x=>x.status==='ok').length;document.getElementById('financeReadout').innerHTML=`<div class="lf-signal"><span>UG debt session</span><strong>${esc(d.session||'Current')}</strong></div><div class="lf-signal"><span>Outstanding UG fees</span><strong>${fmt(d.amount||0)}</strong></div><div class="lf-signal"><span>Students owing</span><strong>${count(d.students||0)}</strong></div><div class="lf-signal"><span>School coverage</span><strong>${online}/${(data.systems||[]).length} connected</strong></div><div class="lf-signal"><span>Latest successful payment</span><strong>${time(t.last_payment_at)}</strong></div>`}
    function render(data){if(!data||!data.success)return;const t=data.totals||{},d=data.debt||{};set('kpiPaid',fmt(t.paid_amount));set('kpiCount',count(t.payment_count));set('kpiDebt',fmt(t.ug_debt_amount));set('kpiDebtStudents',count(t.ug_debt_students));set('financeUpdated','Updated '+new Date(data.updated_at||Date.now()).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'}));drawSystems(data.systems);drawDebt(data.debt_levels,d.amount);drawServices(data.service_summary);drawSchoolServices(data.systems);drawTrend(data.trend);drawReadout(data);document.getElementById('financeAlert').classList.toggle('show',(data.systems||[]).some(x=>x.status!=='ok'&&x.status!=='syncing'))}
    async function refresh(){if(inFlight)return;inFlight=true;try{const response=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error('unavailable');render(await response.json())}catch(e){document.getElementById('financeAlert').classList.add('show');set('financeUpdated','Sync unavailable · retrying')}finally{inFlight=false}}
    render(initial);sessionSelect?.addEventListener('change',refresh);setInterval(refresh,10000)
})();
</script>
